const backgroundDialog=$('#background-dialog'),exportDialog=$('#export-dialog');let backgroundImageUrl='',pendingExportHandle=null,pendingExportName='';
function refreshBackgroundPreview(){const color=$('#bg-modal-color').value,saturation=$('#bg-modal-saturation').value,brightness=$('#bg-modal-brightness').value,contrast=$('#bg-modal-contrast').value,blur=$('#bg-modal-blur').value,hue=$('#bg-modal-hue').value,preview=$('#background-live-preview');preview.style.backgroundColor=color;preview.style.backgroundImage=backgroundImageUrl?`url("${backgroundImageUrl}")`:'';preview.style.filter=`saturate(${saturation}%) brightness(${brightness}%) contrast(${contrast}%) blur(${blur}px) hue-rotate(${hue}deg)`;stage.style.filter=`saturate(${saturation}%) brightness(${brightness}%) contrast(${contrast}%) hue-rotate(${hue}deg)`;['saturation','brightness','contrast','blur','hue'].forEach(id=>{$('#bg-modal-'+id+'-out').textContent=$('#bg-modal-'+id).value+(id==='blur'?' px':id==='hue'?'°':' %')})}
const backgroundBaseId=id=>id==='color'?'bg-color':id;
function openBackgroundDialog(){['color','saturation','brightness'].forEach(id=>{$('#bg-modal-'+id).value=$('#'+backgroundBaseId(id)).value});refreshBackgroundPreview();backgroundDialog.showModal()}
$('#background-settings').addEventListener('click',openBackgroundDialog);$('#bg-modal-image').addEventListener('click',()=>$('#bg-image').click());
['color','saturation','brightness','contrast','blur','hue'].forEach(id=>$('#bg-modal-'+id).addEventListener('input',()=>{if(id==='color'||id==='saturation'||id==='brightness'){const target=$('#'+backgroundBaseId(id));target.value=$('#bg-modal-'+id).value;target.dispatchEvent(new Event('input',{bubbles:true}))}refreshBackgroundPreview()}));
$('#bg-image').addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;backgroundImageUrl=URL.createObjectURL(file);refreshBackgroundPreview()});

function replaceExportButton(id){const old=$(id),fresh=old.cloneNode(true);old.replaceWith(fresh);return fresh}
const exportButtons={video:replaceExportButton('#record'),stl:replaceExportButton('#stl'),gif:replaceExportButton('#gif'),sticker:replaceExportButton('#sticker')};
function cleanExportBase(){return ($('#export-file-name').value.trim()||fileName.replace(/\.[^/.]+$/,'')||'kanaforge').replace(/[\\/:*?"<>|]/g,'-')}
function openExportDialog(type){if(!mesh&&type!=='stl')return;$('#export-type').value=type;$('#export-profile').value=$('#profile').value;$('#export-quality').value=$('#quality').value;$('#export-duration').value=$('#duration').value;$('#export-file-name').value=fileName.replace(/\.[^/.]+$/,'')||'kanaforge';$('#export-dialog-title').textContent=type==='stl'?'Exporter le modèle 3D':'Préparer le fichier';exportDialog.showModal()}
Object.entries(exportButtons).forEach(([type,button])=>button.addEventListener('click',()=>openExportDialog(type)));
async function chooseExportLocation(type,name){if(!window.showSaveFilePicker)return{handle:null,cancelled:false};const videoMime=type==='video'?preferredVideoType():null,extension={video:videoMime?.startsWith('video/mp4')?'mp4':'webm',gif:'gif',sticker:'webp',stl:'stl'}[type],mime={video:videoMime||'video/webm',gif:'image/gif',sticker:'image/webp',stl:'model/stl'}[type];try{return{handle:await window.showSaveFilePicker({suggestedName:`${name}.${extension}`,types:[{description:'Fichier KanaForge',accept:{[mime]:['.'+extension]}}]}),cancelled:false}}catch(error){if(error.name!=='AbortError')console.warn(error);return{handle:null,cancelled:error.name==='AbortError'}}}
function blobAsBase64(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)})}
async function saveExportFile(blob,name){if(pendingExportHandle){const writer=await pendingExportHandle.createWritable();await writer.write(blob);await writer.close();pendingExportHandle=null;return}if(Capacitor.isNativePlatform()){const saved=await Filesystem.writeFile({path:`KanaForge/${name}`,data:await blobAsBase64(blob),directory:Directory.Documents,recursive:true});try{const available=await Share.canShare();if(available.value)await Share.share({title:'Rendu KanaForge',text:'Choisissez où enregistrer ou partager votre rendu.',files:[saved.uri],dialogTitle:'Exporter le rendu KanaForge'})}catch(error){console.warn('Partage Android indisponible',error)}return}const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1200)}
$('#export-confirm').addEventListener('click',async event=>{event.preventDefault();const type=$('#export-type').value;$('#profile').value=$('#export-profile').value;$('#quality').value=$('#export-quality').value;$('#duration').value=$('#export-duration').value;refreshExportUi();pendingExportName=cleanExportBase();const target=await chooseExportLocation(type,pendingExportName);if(target.cancelled){pendingExportName='';return}pendingExportHandle=target.handle;exportDialog.close();if(type==='video')exportVideoConfigured();else if(type==='gif')exportGif();else if(type==='sticker')exportSticker();else exportStlConfigured()});
async function exportGif(){if(!mesh)return;const gif=GIFEncoder(),savedRotation=mesh.rotation.y,profile=exportOptions(),scale=Math.min(1,640/Math.max(profile.w,profile.h)),width=Math.round(profile.w*scale/2)*2,height=Math.round(profile.h*scale/2)*2,format=transparentBg?'rgba4444':'rgb565',oldSize=renderer.getSize(new THREE.Vector2()),oldRatio=renderer.getPixelRatio(),oldAspect=camera.aspect;renderer.setPixelRatio(1);renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix();const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=width;canvas.height=height;for(let i=0;i<30;i++){mesh.rotation.y=savedRotation+i*Math.PI*2/30;renderer.render(scene,camera);ctx.drawImage(renderer.domElement,0,0,width,height);const data=ctx.getImageData(0,0,width,height).data,palette=quantize(data,128,{format,oneBitAlpha:transparentBg}),index=applyPalette(data,palette,format);gif.writeFrame(index,width,height,{palette,delay:55,repeat:0,transparent:transparentBg})}mesh.rotation.y=savedRotation;renderer.setPixelRatio(oldRatio);renderer.setSize(oldSize.x,oldSize.y,false);camera.aspect=oldAspect;camera.updateProjectionMatrix();gif.finish();await saveExportFile(new Blob([gif.bytes()],{type:'image/gif'}),`${pendingExportName||'kanaforge'}.gif`);pendingExportName='';$('#status').innerHTML='<i></i> GIF prêt au téléchargement'}
