function enhanceCommunication(){const field=$('#communication-copy'),preview=$('#communication-preview'),mailStatus=$('#mail-status');let tone='chaleureux';const draft=()=>{const hello=tone==='premium'?'Bonjour, merci pour votre message.':'Bonjour, merci pour votre message !';const ending=tone==='direct'?'Envoyez-moi vos créneaux souhaités et une référence visuelle.':'Je serai ravie d’échanger avec vous sur votre projet. Pouvez-vous me transmettre vos disponibilités et une ou deux références ?';preview.textContent=`${hello}\n\nJ’ai bien reçu votre demande : ${field.value.trim()||'votre projet de tatouage'}.\n\n${ending}\n\nÀ bientôt,\nVotre studio`};draft();$('#agent-tone').onclick=e=>{const b=e.target.closest('button');if(!b)return;tone=b.dataset.tone;document.querySelectorAll('#agent-tone button').forEach(x=>x.classList.toggle('is-selected',x===b));draft()};$('#agent-draft-button').onclick=draft;document.querySelectorAll('.mail-item').forEach(item=>item.onclick=()=>{document.querySelectorAll('.mail-item').forEach(x=>x.classList.toggle('is-selected',x===item));field.value=item.dataset.mail;draft()});$('#mail-connect-button').onclick=()=>mailStatus.textContent='La connexion sécurisée Gmail/Outlook sera proposée dès qu’un compte professionnel sera autorisé.';$('#communication-copy-button').onclick=async()=>{try{await navigator.clipboard.writeText(preview.textContent);setStatus('Réponse copiée : relisez-la puis envoyez-la depuis votre boîte pro.')}catch{setStatus('Sélectionnez la réponse puis copiez-la.')}}}
