function activateStudio(name){bodyPreview?.dispose?.();studioHub.dataset.mode=name;modulePanel.className=`hub-panel studio-module mode-${name}`;document.querySelectorAll('[data-studio]').forEach(b=>b.classList.toggle('nav-active',b.dataset.studio===name));if(name==='object3d'){studioHub.hidden=true;object3dApp.hidden=false;return}object3dApp.hidden=true;studioHub.hidden=false;const copy=studioCopy[name];homePanel.hidden=!!copy;modulePanel.hidden=!copy;if(!copy){$('#studio-hub-kicker').textContent='KANAFORGE / STUDIO TATOUAGE';$('#studio-hub-title').innerHTML='Votre studio, <em>en un seul lieu.</em>';$('#studio-hub-intro').textContent='Choisissez un laboratoire pour préparer, placer et partager vos créations.';return}$('#studio-hub-kicker').textContent=copy[0];$('#studio-hub-title').innerHTML=copy[1];$('#studio-hub-intro').textContent=copy[2];modulePanel.innerHTML=moduleTemplates[name];if(name!=='placement')bindModule(name);bindBusinessModule(name);persistBusiness(name);if(name==='placement')initBodyStudio();if(name==='communication')enhanceCommunication()}
