document.addEventListener('click',event=>{if(!Capacitor.isNativePlatform()||!event.target.closest('#client-quote-export'))return;event.preventDefault();event.stopImmediatePropagation();const client=$('#client-name').value||'Client',body=$('#client-body').value||'Zone à définir',amount=$('#client-quote').value||'À définir',deadline=$('#client-deadline').value||'À confirmer',notes=$('#client-notes').value||'—',status=$('#client-status .is-selected')?.textContent||'Nouveau',text=`KANAFORGE — DEVIS TATOUAGE\n\nClient : ${client}\nZone : ${body}\nDélai souhaité : ${deadline}\nStatut : ${status}\nMontant estimatif : ${amount} €\n\nNotes du projet\n${notes}\n\nDocument préparé dans KanaForge. À valider avec le client.`;saveExportFile(new Blob([text],{type:'text/plain;charset=utf-8'}),`devis-${client.replace(/[^a-z0-9]+/gi,'-').toLowerCase()||'kanaforge'}.txt`).then(()=>setStatus('Devis exporté : choisissez son emplacement dans le panneau Android.')).catch(()=>setStatus('L’export du devis a échoué.'));},true);
