const processingNav=document.createElement('button');processingNav.dataset.studio='processing';processingNav.innerHTML='IA &amp; Processing <small>NOUVEAU</small>';processingNav.onclick=()=>activateStudio('processing');document.querySelector('[data-studio="flash"]')?.insertAdjacentElement('afterend',processingNav);
moduleTemplates.processing=`<div class="module-layout processing-layout"><section class="module-card"><p class="section-tag">PROCESSING / VECTEUR</p><h2>Décrivez votre motif</h2><label>Prompt créatif<textarea id="processing-prompt">Ornement organique noir, symétrique et fluide</textarea></label><div class="choice-row" id="processing-style"><button class="is-selected" data-processing="ornament">Ornement</button><button data-processing="waves">Ondes</button><button data-processing="glyph">Glyphe</button></div><label>Densité <output id="processing-density-out">64 %</output></label><input id="processing-density" type="range" min="20" max="100" value="64"/><button class="module-action" id="processing-generate">Générer le vecteur</button><p class="module-status" id="processing-status">Génération locale prête · aucun dessin n’est envoyé.</p></section><aside class="module-card"><p class="section-tag">CHATGPT SÉCURISÉ · OPTIONNEL</p><h2>Connecter votre IA</h2><p>Ajoutez l’adresse de votre serveur IA. La clé OpenAI reste sur ce serveur, jamais dans KanaForge.</p><label>Adresse du serveur IA<input id="processing-endpoint" type="url" placeholder="https://votre-serveur.example/generate-vector"/></label><label class="ai-consent"><input id="processing-consent" type="checkbox"/> J’autorise l’envoi de ce prompt au serveur choisi.</label><button class="secondary" id="processing-ai-generate">Générer avec ChatGPT</button><button class="module-action" id="processing-to-3d" disabled>Utiliser dans le labo objet 3D</button></aside><section class="module-card processing-preview-card"><p class="section-tag">APERÇU VECTORIEL</p><div id="processing-preview" aria-label="Aperçu du motif généré"></div><small>Le bouton d’envoi convertit le SVG en dessin, prêt à être modélisé.</small></section></div>`;
studioCopy.processing=['IA & PROCESSING','Générez un <em>motif vectoriel.</em>','Décrivez une intention, vérifiez le résultat, puis envoyez-le vers le labo objet 3D.'];
function buildProcessingSvg(style,density,prompt){const n=Math.round(5+density/12),seed=[...prompt].reduce((a,c)=>a+c.charCodeAt(0),0),accent=seed%2?'#111216':'#15151a';let shapes='';if(style==='waves'){for(let i=0;i<n;i++){const y=60+i*280/(n-1),amp=18+(seed+i*13)%38;shapes+=`<path d="M25 ${y} C110 ${y-amp} 170 ${y+amp} 250 ${y} S390 ${y-amp} 475 ${y}"/>`}}else if(style==='glyph'){for(let i=0;i<n;i++){const a=i/n*Math.PI*2,r=38+i*13,x=250+Math.cos(a)*r,y=200+Math.sin(a)*r;shapes+=`<path d="M250 200 L${x.toFixed(1)} ${y.toFixed(1)} M${(250+Math.cos(a+.7)*r).toFixed(1)} ${(200+Math.sin(a+.7)*r).toFixed(1)} L${(250+Math.cos(a+1.4)*(r+25)).toFixed(1)} ${(200+Math.sin(a+1.4)*(r+25)).toFixed(1)}"/>`}}else{for(let i=0;i<n;i++){const r=18+i*16,turn=seed%31;shapes+=`<path d="M250 ${200-r} C${250+r+turn} ${200-r} ${250+r+turn} ${200+r} 250 ${200+r} C${250-r-turn} ${200+r} ${250-r-turn} ${200-r} 250 ${200-r}Z" transform="rotate(${i*360/n} 250 200)"/>`}}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 400"><rect width="500" height="400" fill="white"/><g fill="none" stroke="${accent}" stroke-width="${Math.max(2,Math.round(density/18))}" stroke-linecap="round" stroke-linejoin="round">${shapes}</g></svg>`}
function bindProcessingStudio(){let svg='';const preview=$('#processing-preview'),status=$('#processing-status'),to3d=$('#processing-to-3d'),style=()=>$('#processing-style .is-selected')?.dataset.processing||'ornament',show=next=>{svg=next;preview.innerHTML=svg;to3d.disabled=false},makeLocal=()=>{show(buildProcessingSvg(style(),+$('#processing-density').value,$('#processing-prompt').value));status.textContent='Vecteur créé localement · modifiez le prompt ou envoyez-le en 3D.'};$('#processing-density').oninput=()=>$('#processing-density-out').textContent=$('#processing-density').value+' %';$('#processing-style').onclick=e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('#processing-style button').forEach(x=>x.classList.toggle('is-selected',x===b));makeLocal()};$('#processing-generate').onclick=makeLocal;$('#processing-ai-generate').onclick=async()=>{const endpoint=$('#processing-endpoint').value.trim();if(!endpoint||!$('#processing-consent').checked){status.textContent='Ajoutez l’adresse de votre serveur IA et confirmez l’envoi.';return}status.textContent='Demande envoyée au serveur IA…';try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:$('#processing-prompt').value,format:'svg',style:style(),density:+$('#processing-density').value})}),result=await response.json();if(!response.ok||typeof result.svg!=='string')throw new Error();show(result.svg);status.textContent='Vecteur reçu de ChatGPT · vérifiez-le puis envoyez-le en 3D.'}catch{status.textContent='Le serveur IA n’a pas répondu avec un SVG. Vérifiez son adresse et son format.'}};to3d.onclick=()=>{if(!svg)return;localStorage.setItem('kanaforge-pending-drawing',JSON.stringify({image:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg),name:'processing-vector'}));location.href='./object3d.html'};makeLocal()}
const originalActivateStudio=activateStudio;activateStudio=function(name){originalActivateStudio(name);if(name==='processing')bindProcessingStudio()};
